"""What the settings page offers: pinned models and engines (catalog.json, regenerated by tools/refresh_catalog.py), plus
facts about this computer (platform, RAM) that decide the engine and which models fit."""
from __future__ import annotations

import ctypes
import functools
import json
import os
import platform
import subprocess
import sys
from pathlib import Path

CATALOG_FILE = Path(__file__).with_name("catalog.json")
BACKENDS = ("mlx", "llamacpp")


@functools.lru_cache(maxsize=1)
def load() -> dict:
    return json.loads(CATALOG_FILE.read_text(encoding="utf-8"))


def models() -> list[dict]:
    return load()["models"]


def get(model_id: str) -> dict | None:
    return next((m for m in models() if m["id"] == model_id), None)


def platform_key() -> str:
    """Key of the llama.cpp asset for this computer, e.g. "darwin-arm64"."""
    system = {"darwin": "darwin", "win32": "windows"}.get(sys.platform, "linux")
    machine = platform.machine().lower()
    arch = "arm64" if machine in ("arm64", "aarch64") and system != "linux" else "aarch64" if machine in ("arm64", "aarch64") else "x86_64"
    if system == "windows" and arch == "aarch64":
        arch = "arm64"
    return f"{system}-{arch}"


def auto_backend() -> str:
    """MLX on Apple-silicon Macs (fastest there), llama.cpp everywhere else."""
    return "mlx" if platform_key() == "darwin-arm64" and sys.version_info >= (3, 11) else "llamacpp"


def total_ram_gb() -> float:
    try:
        if sys.platform == "darwin":
            return int(subprocess.check_output(["sysctl", "-n", "hw.memsize"], text=True, timeout=5)) / 2**30
        if sys.platform == "win32":
            class MemStatus(ctypes.Structure):
                _fields_ = [("length", ctypes.c_ulong), ("load", ctypes.c_ulong), ("total", ctypes.c_ulonglong), ("avail", ctypes.c_ulonglong),
                            ("ptotal", ctypes.c_ulonglong), ("pavail", ctypes.c_ulonglong), ("vtotal", ctypes.c_ulonglong),
                            ("vavail", ctypes.c_ulonglong), ("ext", ctypes.c_ulonglong)]
            st = MemStatus()
            st.length = ctypes.sizeof(MemStatus)
            ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(st))        # type: ignore[attr-defined]
            return st.total / 2**30
        return os.sysconf("SC_PAGE_SIZE") * os.sysconf("SC_PHYS_PAGES") / 2**30
    except (OSError, ValueError, subprocess.SubprocessError, AttributeError):
        return 0.0


def model_bytes(m: dict, backend: str) -> int:
    if backend == "mlx":
        return sum(f["size"] for f in m["mlx"]["files"])
    return m["gguf"]["size"]


def licence(m: dict, backend: str) -> str:
    return (m["mlx"] if backend == "mlx" else m["gguf"]).get("license") or ""


def recommended_for(ram_gb: float) -> str:
    """The project default when it fits this computer, otherwise the largest model that does (or the smallest one)."""
    default = get(load()["recommended"])
    if ram_gb >= default["ram_gb"]:
        return default["id"]
    fitting = [m for m in models() if m["ram_gb"] <= ram_gb]
    return max(fitting, key=lambda m: m["ram_gb"])["id"] if fitting else min(models(), key=lambda m: m["ram_gb"])["id"]
